import random, math

def round_loser(s): return min(s, key=lambda k: (s[k], k))
def irv_winner(s):
    a = dict(s)
    while len(a) > 1: del a[round_loser(a)]
    return next(iter(a))
def min_gap(s):
    a, g = dict(s), math.inf
    while len(a) > 1:
        lo = round_loser(a)
        g = min(g, min(v for k,v in a.items() if k!=lo) - a[lo])
        del a[lo]
    return g

scores = {0: 1.0, 1: 3.5, 2: 2.0, 3: 5.0, 4: 4.2}
gamma = min_gap(scores)
eps_safe = gamma/2 - 0.01

rng = random.Random(42)
flips = sum(1 for _ in range(10000)
            if irv_winner({k: v+rng.uniform(-eps_safe,eps_safe) for k,v in scores.items()}) != irv_winner(scores))
print(f"γ={gamma:.3f}, ε={eps_safe:.3f}, 2ε<γ: {2*eps_safe<gamma}")
print(f"Flips within certified radius: {flips}/10000 (guaranteed 0)")

